// One email in, one item out — with its binary attachments untouched.
// The Gmail Trigger (simple: false) puts attachments on the item's binary.
// This node also folds in the email fields (from / subject / date), so there
// is deliberately no separate normalise step that could drop the binary.
const item = $input.first();
const json = item.json || {};
const binary = item.binary || {};
let pdfKey = '';
for (const key of Object.keys(binary)) {
  const file = binary[key] || {};
  const name = (file.fileName || '').toLowerCase();
  const mime = (file.mimeType || '').toLowerCase();
  if (name.endsWith('.pdf') || mime === 'application/pdf') { pdfKey = key; break; }
}
const from = json.from || {};
let fromEmail = '';
if (typeof from === 'object') {
  const values = from.value || [];
  fromEmail = (values[0] && values[0].address) || from.text || '';
} else if (from) {
  fromEmail = String(from);
}
return [{ json: {
  from_email: fromEmail || json.sender || '',
  subject: json.subject || '',
  received_at: json.date || json.internalDate || new Date().toISOString(),
  pdf_binary_key: pdfKey,
  pdf_file_name: pdfKey ? (binary[pdfKey].fileName || '') : ''
}, binary: binary }];

