// Safe-parse the AI reply, coerce the money fields to real numbers, and flag
// whether the row is complete enough to trust without a second look.
const first = $input.first().json || {};
const choices = first.choices || [];
const raw = (choices[0] && choices[0].message && choices[0].message.content) || '';
let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) { parsed = {}; }
const src = $('Find the PDF Attachment').first().json;
const num = (v) => {
  if (v === null || v === undefined || v === '') return '';
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? '' : n;
};
const vendor = typeof parsed.vendor === 'string' ? parsed.vendor.trim() : '';
const total = num(parsed.total);
return [{ json: {
  vendor: vendor,
  invoice_date: typeof parsed.invoice_date === 'string' ? parsed.invoice_date : '',
  invoice_number: (parsed.invoice_number === null || parsed.invoice_number === undefined) ? '' : String(parsed.invoice_number),
  subtotal: num(parsed.subtotal),
  tax: num(parsed.tax),
  total: total,
  currency: typeof parsed.currency === 'string' ? parsed.currency.toUpperCase() : '',
  from_email: src.from_email || '',
  subject: src.subject || '',
  received_at: src.received_at || '',
  complete: !!(vendor && total !== '')
} }];

